          val unknownFields = reader.forEachTag { tag ->
            when (tag) {
              1 -> pin = ProtoAdapter.BOOL.decode(reader)
              2 -> unpin = ProtoAdapter.BOOL.decode(reader)
              3 -> pin_end_time = ProtoAdapter.INT64.decode(reader)
              4 -> sub_goal_id = ProtoAdapter.INT64.decode(reader)
              5 -> sub_goal_id_str = ProtoAdapter.STRING.decode(reader)
              else -> reader.readUnknownField(tag)
            }
          }
          return GoalPinInfo(
            pin = pin,
            unpin = unpin,
            pin_end_time = pin_end_time,
            sub_goal_id = sub_goal_id,
            sub_goal_id_str = sub_goal_id_str,
            unknownFields = unknownFields
          )
        }

        override fun redact(`value`: GoalPinInfo): GoalPinInfo = value.copy(
          unknownFields = ByteString.EMPTY
        )
      }

      private const val serialVersionUID: Long = 0L
    }
  }
}
